import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),n={name:"guide/security.md"};function i(o,e,d,l,c,h){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><ul><li><strong>Sign-in:</strong> every API route needs a session or an <a href="./api-tokens">API token</a>, except creating the first administrator, signing in and accepting an invitation. Repeated failed attempts from the same address are locked out for a while. Accounts can add a <a href="./two-factor">second factor</a>, and the administrator can require it for everyone.</li><li><strong>Roles:</strong> every operation checks the caller&#39;s role in the workspace it touches, and lists and live updates only carry the workspaces a person belongs to. See <a href="./members">Members and roles</a>.</li><li><strong>The console&#39;s address:</strong> it is published with a Let&#39;s Encrypt certificate, and plain HTTP redirects to HTTPS. Orbit only answers requests that come through Traefik with a secret that changes every time Orbit starts, and the firewall keeps its port reachable only from the server and its workloads.</li><li><strong>Agents:</strong> they need a client certificate from Orbit&#39;s own certificate authority that is not revoked or expired.</li><li><strong>Added servers:</strong> their SSH host keys are pinned when you confirm the fingerprint, and every later connection refuses a different key. Pasted private keys live only in memory.</li><li><strong>Secrets at rest:</strong> variables marked secret, database passwords, the GitHub App&#39;s key and the GitLab and Bitbucket tokens are sealed with AES-256-GCM, with a key kept outside Orbit&#39;s database. Passwords are hashed with Argon2id, and session, enrollment and API tokens are stored only as hashes. Orbit&#39;s data directory is readable only by root.</li><li><strong>Logs:</strong> secrets and common credential patterns are redacted before anything is stored. See <a href="./operating#redaction">Running Orbit</a>.</li><li><strong>Terminals:</strong> a shell in an instance or a database needs a signed-in member with the role, never an API token. The activity records who opened and closed which instance; keystrokes and output are never recorded. See <a href="./applications#terminal">Applications</a>.</li><li><strong>Releases:</strong> every release is signed. The console refuses to update from a release whose signature does not match the key pinned in the running Orbit.</li><li><strong>Pull request previews:</strong> pull requests from forks never run on your servers.</li></ul>',2)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
